using System;
using System.IO;
using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

namespace SecureService
{
    public class CryptoProvider
    {
        private readonly byte[] _masterKey;
        private readonly ILogger<CryptoProvider> _logger;

        public CryptoProvider(ILogger<CryptoProvider> logger)
        {
            _logger = logger;
            _masterKey = Convert.FromBase64String(Environment.GetEnvironmentVariable("MASTER_KEY") ?? Convert.ToBase64String(RandomNumberGenerator.GetBytes(32)));
        }

        public DecryptionResult Decrypt(byte[] ciphertext)
        {
            if (ciphertext == null || ciphertext.Length < 32)
                return DecryptionResult.InvalidInput();

            try
            {
                byte[] iv = new byte[16];
                Buffer.BlockCopy(ciphertext, 0, iv, 0, 16);
                byte[] encrypted = new byte[ciphertext.Length - 16];
                Buffer.BlockCopy(ciphertext, 16, encrypted, 0, encrypted.Length);

                using var aes = Aes.Create();
                aes.Key = _masterKey;
                aes.IV = iv;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;

                using var decryptor = aes.CreateDecryptor();
                using var ms = new MemoryStream(encrypted);
                using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);
                using var reader = new MemoryStream();
                cs.CopyTo(reader);
                return DecryptionResult.Success(reader.ToArray());
            }
            catch (CryptographicException)
            {
                return DecryptionResult.PaddingError();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Unexpected decryption error");
                return DecryptionResult.UnexpectedError();
            }
        }
    }

    public class DecryptionResult
    {
        public enum ResultCode { Ok, InvalidInput, BadPadding, Unexpected }
        public ResultCode Code { get; private set; }
        public byte[]? Plaintext { get; private set; }

        public static DecryptionResult Success(byte[] data) => new() { Code = ResultCode.Ok, Plaintext = data };
        public static DecryptionResult InvalidInput() => new() { Code = ResultCode.InvalidInput };
        public static DecryptionResult PaddingError() => new() { Code = ResultCode.BadPadding };
        public static DecryptionResult UnexpectedError() => new() { Code = ResultCode.Unexpected };
    }

    public class GracefulShutdownService : IHostedService
    {
        private readonly ILogger<GracefulShutdownService> _logger;
        private readonly IHostApplicationLifetime _lifetime;
        private int _activeRequests;

        public GracefulShutdownService(ILogger<GracefulShutdownService> logger, IHostApplicationLifetime lifetime)
        {
            _logger = logger;
            _lifetime = lifetime;
        }

        public int ActiveRequests => _activeRequests;
        public void IncrementRequests() => Interlocked.Increment(ref _activeRequests);
        public void DecrementRequests() => Interlocked.Decrement(ref _activeRequests);

        public Task StartAsync(CancellationToken ct)
        {
            _lifetime.ApplicationStopping.Register(() =>
            {
                _logger.LogInformation("Shutdown initiated, waiting for {Count} active requests", _activeRequests);
                var deadline = DateTime.UtcNow.AddSeconds(30);
                while (_activeRequests > 0 && DateTime.UtcNow < deadline)
                    Thread.Sleep(100);
            });
            return Task.CompletedTask;
        }

        public Task StopAsync(CancellationToken ct) => Task.CompletedTask;
    }

    public class DecryptionMiddleware
    {
        private readonly RequestDelegate _next;
        private readonly CryptoProvider _crypto;
        private readonly GracefulShutdownService _shutdown;
        private readonly ILogger<DecryptionMiddleware> _logger;

        public DecryptionMiddleware(RequestDelegate next, CryptoProvider crypto, GracefulShutdownService shutdown, ILogger<DecryptionMiddleware> logger)
        {
            _next = next;
            _crypto = crypto;
            _shutdown = shutdown;
            _logger = logger;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            if (context.Request.Path != "/api/decrypt")
            {
                await _next(context);
                return;
            }

            _shutdown.IncrementRequests();
            try
            {
                using var bodyReader = new StreamReader(context.Request.Body);
                var base64Body = await bodyReader.ReadToEndAsync();

                if (string.IsNullOrWhiteSpace(base64Body))
                {
                    context.Response.StatusCode = 400;
                    await context.Response.WriteAsync("Missing ciphertext");
                    return;
                }

                byte[] ciphertext;
                try
                {
                    ciphertext = Convert.FromBase64String(base64Body.Trim());
                }
                catch (FormatException)
                {
                    context.Response.StatusCode = 400;
                    await context.Response.WriteAsync("Invalid base64");
                    return;
                }

                var result = _crypto.Decrypt(ciphertext);

                switch (result.Code)
                {
                    case DecryptionResult.ResultCode.Ok:
                        context.Response.StatusCode = 200;
                        await context.Response.WriteAsync(Convert.ToBase64String(result.Plaintext!));
                        break;
                    case DecryptionResult.ResultCode.InvalidInput:
                        context.Response.StatusCode = 400;
                        await context.Response.WriteAsync("Invalid ciphertext length");
                        break;
                    case DecryptionResult.ResultCode.BadPadding:
                        context.Response.StatusCode = 400;
                        await context.Response.WriteAsync("Decryption failed: padding invalid");
                        break;
                    case DecryptionResult.ResultCode.Unexpected:
                        context.Response.StatusCode = 500;
                        await context.Response.WriteAsync("Internal error");
                        break;
                }
            }
            finally
            {
                _shutdown.DecrementRequests();
            }
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddSingleton<CryptoProvider>();
            builder.Services.AddSingleton<GracefulShutdownService>();
            builder.Services.AddHostedService(sp => sp.GetRequiredService<GracefulShutdownService>());

            var app = builder.Build();
            app.UseMiddleware<DecryptionMiddleware>();
            app.Run();
        }
    }
}
